def pagos_de_los_egresos_pagados(apps, schema_editor):
    """Cada egreso marcado como pagado pasa a tener su pago (total) registrado."""
    Egreso = apps.get_model("finanzas", "Egreso")
    Pago = apps.get_model("finanzas", "Pago")
    Pago.objects.bulk_create(
        [Pago(egreso_id=e.pk, fecha=e.fecha_pago or e.fecha, monto=e.monto, medio=e.medio_pago, automatico=True)
         for e in Egreso.objects.filter(pagado=True, monto__gt=0).only("pk", "fecha", "fecha_pago", "monto", "medio_pago")],
        batch_size=2000)


